using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.NTF.NotificacionesVisualizadas;using GraphApi.Services.NTF.NotificacionesVisualizadas;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.NTF.NotificacionesVisualizadas{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de NotificacionesVisualizadas: creación, actualización y eliminación.")]    public class NotificacionesVisualizadasMutation    {        [Authorize]        [GraphQLName("createNotificacionesVisualizadas")]        [GraphQLDescription("Crea un nuevo NotificacionesVisualizada usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadNotificacionesVisualizadas> CreateNotificacionesVisualizadasAsync(            [GraphQLDescription("Datos necesarios para crear el NotificacionesVisualizada.")]            clCreateNotificacionesVisualizadas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de NotificacionesVisualizada.")]            INotificacionesVisualizadasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateNotificacionesVisualizadas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateNotificacionesVisualizadas")]        [GraphQLDescription("Actualiza los campos especificados de un NotificacionesVisualizada existente.")]        public async Task<clReadNotificacionesVisualizadas?> UpdateNotificacionesVisualizadasAsync(            [GraphQLDescription("Datos del NotificacionesVisualizada a actualizar.")]            clUpdateNotificacionesVisualizadas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de NotificacionesVisualizada.")]            INotificacionesVisualizadasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateNotificacionesVisualizadas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteNotificacionesVisualizadas")]        [GraphQLDescription("Elimina un NotificacionesVisualizada por su ID.")]        public async Task<bool> delNotificacionesVisualizadasAsync(            [GraphQLDescription("ID del NotificacionesVisualizada a eliminar.")]            int nNotificacionesVisualizadasID,            [Service]            [GraphQLDescription("Servicio para operaciones de NotificacionesVisualizada.")]            INotificacionesVisualizadasService objService        )        {            return await objService.DeleteNotificacionesVisualizadas(nNotificacionesVisualizadasID);        }    }}